import { render } from '@solidjs/web';
import { createSignal } from 'solid-js';
import Button from './button';
import './styles.css';

function App() {
  const [count, setCount] = createSignal(0);

  return (
    <>
      <p>Saved {count()} times</p>
      <Button variant="primary" onClick={() => setCount((n) => n + 1)}>
        Save
      </Button>
      <Button
        variant="danger"
        disabled={count() === 0}
        onClick={() => setCount(0)}
      >
        Reset
      </Button>
    </>
  );
}

render(() => <App />, document.getElementById('app'));

export default function Button(props) {
  return <button class={['btn', props.variant]}>{props.children}</button>;
}

.btn {
  margin-right: 0.5rem;
  padding: 0.4rem 1rem;
  border: none;
  border-radius: 4px;
  color: white;
}

.primary {
  background: #446b9e;
}

.danger {
  background: #c0392b;
}

.btn:disabled {
  opacity: 0.4;
}

import { render } from '@solidjs/web';
import { createSignal } from 'solid-js';
import Button from './button';
import './styles.css';

function App() {
  const [count, setCount] = createSignal(0);

  return (
