render(() => <App />, document.getElementById('app'));

import { omit } from 'solid-js';

export default function Button(props) {
  const others = omit(props, 'variant', 'children');

  return (
    <button {...others} class={['btn', props.variant]}>
      {props.children}
    </button>
  );
}

